def fact_reply(kind: str, *, message: str, items: list[Any], now: datetime,
               place_source: Any = None, item: Any = None) -> tuple[str, dict[str, Any]]:
    """(답, 근거). 근거에는 무엇을 보고 답했는지(`kind` · `item` · `day` · `lookups`)와 **문장을 누가 썼는지**
    (`writer: "template"`)를 싣는다.

    `item` — ★`[2026-09-29]` 결정 단위가 고른 대상(서버가 id 로 확인한 항목). 주면 문장 낱말로 다시 찾지 않는다."""
    if item is not None:
        day = _local(item.starts_at).date()
    else:
        day, item = target(items, message, now)
    basis: dict[str, Any] = {"kind": kind, "writer": "template", "day": day.isoformat() if day else None,
                             "item": item.title if item else None, "lookups": None}
    stops = _stops(items)
    if not stops:
        return "이 여행에는 아직 일정이 없어요.", basis
    days = sorted({_local(s.starts_at).date() for s in stops})

    if kind == "day":
        day = day or (_local(now).date() if _local(now).date() in days else days[0])
        basis["day"] = day.isoformat()
        return _day_answer(items, day, days), basis
    if kind == "booking":
        if item is not None and not _asked_day(message, now):
            return f"{item.title}({_day_label(_local(item.starts_at).date())} {_hm(item.starts_at)}) — "\
                   f"{booking_fact(item)[1]}.", basis
        day = day or (_local(now).date() if _local(now).date() in days else days[0])
        basis["day"] = day.isoformat()
        return _booking_answer(stops, day, days), basis
    if kind == "next":
        return _next_answer(items, stops, item, now), basis
    if item is None:
        titles = " · ".join(f"{_hm(s.starts_at)} {s.title}" for s in stops[:8])
        return (f"어느 일정을 물으신 건지 찾지 못했어요. 일정 이름이나 시각을 같이 적어 주세요.\n"
                f"이 여행의 일정 — {titles}{' …' if len(stops) > 8 else ''}"), basis
    if kind == "move":
        pair = _asked_pair(stops, message)
        if pair is not None:
            basis["item"] = f"{pair[0].title} → {pair[1].title}"
            return _pair_move_answer(items, *pair), basis
        return _move_answer(items, item), basis
    if kind == "time":
        end = f"~{_hm(item.ends_at)}" if item.ends_at else ""
        return f"{item.title} — {_day_label(_local(item.starts_at).date())} {_hm(item.starts_at)}{end}.", basis
    lookup = look_up_place(item.place, place_source) if item.place else None
    basis["lookups"] = lookup
    if kind == "phone":
        name = (item.place or {}).get("name") or item.title
        if lookup and lookup.get("phone"):
            return f"{name} 전화번호는 {lookup['phone']}(출처 {lookup['source']}).", basis
        return f"{name}의 전화번호는 모르겠어요{_lookup_note(lookup)}.", basis
    if kind == "address":
        return _address_answer(item, lookup), basis
    if kind == "hours":
        return _hours_answer(item, lookup), basis
    return _detail_answer(items, item, lookup), basis


def _day_answer(items: list[Any], day: date, days: list[date]) -> str:

    uid = (((place or {}).get("attributes") or {}).get("dining_place_uid") or "").strip()
    if uid:
        try:
            from app.infrastructure.db.session import get_connection

            from app.domains.travel_ops.components.places.place_info import ledger_info

            with get_connection() as conn:
                info = ledger_info(conn, uid)
        except Exception as exc:                              # noqa: BLE001 — 원장을 못 읽어도 관광공사로 간다(이유는 남긴다)
            info = None
            out["failed"].append(f"요식 원장 조회 오류 {type(exc).__name__}")
        if info:
            out["address"], out["phone"] = info.get("address"), info.get("phone")
            if info.get("hours"):
                out["hours_text"] = " · ".join(
                    f"{h['day']} {h['open']}~{h['close']}" + (f"(라스트오더 {h['last_order']})" if h.get("last_order") else "")
                    for h in info["hours"])
                out["hours_label"] = "요식 원장"
            out["source"] = "요식 원장" + (f" · {info['source_note']}" if info.get("source_note") else "")
            if out["address"] and out["hours_text"]:
                return out

    attributes = (place or {}).get("attributes") or {}
    content_id = str(attributes.get("source_content_id") or "")
    type_id = str(attributes.get("source_content_type_id") or "")
    if source is None or not hasattr(source, "operating"):
        out["failed"].append("관광공사 조회가 연결돼 있지 않음")
        return out
    if not content_id or not type_id:
        # ★종류 번호 없이 식별자만 있으면 운영시간 조회(`detailIntro2`)가 「필수 값 없음」으로 실패한다 — 계획 읽기가
        #   종류 번호를 저장하지 않던 때 등록한 장소가 그렇다(ui 세션 실서버 시험 「창덕궁」). 이름·좌표로 다시 찾는다
        # ★`[2026-09-28]` 식별자 없는 장소(공용 장소 행 · 고객 글의 이름으로 붙은 곳)는 같은 이름·종류 + 좌표 500m 로 찾는다.
        #   전에는 「관광공사 식별자가 없는 장소」로 끝나 등록된 「경복궁」의 주소·운영시간이 모름이었다(ui 세션 실측)
        ids, why, _ = find_tour_id(name=str((place or {}).get("name") or ""), kind=str((place or {}).get("kind") or ""),
                                   latitude=(place or {}).get("latitude"), longitude=(place or {}).get("longitude"),
                                   source=source)
        if ids is None:
            out["failed"].append(why)
            return out
        content_id, type_id = ids
    cached = _CACHE.get(content_id)
    if cached and _time.time() - cached[0] < _CACHE_SECONDS and not (out["address"] or out["hours_text"]):
        return dict(cached[1])                                # ★원장 값을 읽었으면 캐시가 덮지 않게 아래서 합친다
    out["source"] = "관광공사" if not out["source"] else out["source"] + " · 관광공사"
    try:
        if not out["address"]:
            common = source.by_content_id(content_id, type_id)
            if common and common.get("address"):
                out["address"] = common["address"]
            else:
                out["failed"].append("주소 조회 결과 없음")
        intro = source.operating(content_id, type_id)
        if intro:
            out["hours_text"], out["rest_text"] = intro.get("usetime_text"), intro.get("restdate_text")
            out["phone"] = out["phone"] or intro.get("info_phone")
        else:
            out["failed"].append("운영시간 조회 결과 없음")
    except Exception as exc:                                  # noqa: BLE001 — 조회 실패도 답에 그대로 말한다
        out["failed"].append(f"조회 오류 {type(exc).__name__}")
        return out
    _CACHE[content_id] = (_time.time(), dict(out))
    return out


def _clean(text: str | None) -> str | None:
    if not text:
        return None
    text = re.sub(r"<br\s*/?>", " / ", str(text), flags=re.I)
    return re.sub(r"\s+", " ", re.sub(r"<[^>]+>", "", text)).strip() or None

"""최근 사실 안내 뒤 숫자 답변이 옛 업무를 재개하지 않는지 확인한다."""
from contextlib import nullcontext
from types import SimpleNamespace
from uuid import uuid4

import pytest

from app.core.contracts import StateConflict
from app.domains.travel_ops.components.conversation import case_dispatch, chat_log


class Conn:
    def __init__(self, rows):
        self.rows = rows
        self.commits = 0

    def cursor(self):
        return nullcontext(self)

    def execute(self, query, args):
        self.args = args

    def fetchall(self):
        return self.rows

    def commit(self):
        self.commits += 1


def prepare(monkeypatch, *, latest="different", explicit=False, token=False,
            replayed=False, extra=False, message="1번", schema=None):
    trip_id, customer_id, waiting, other = uuid4(), uuid4(), uuid4(), uuid4()
    rows = [(waiting, replayed)] + ([(other, False)] if extra else [])
    conn = Conn(rows)
    state = {"trip_message": {"trip_id": str(trip_id)}, "required_input_schema": schema or {
        "required": ["message"], "choices": [{"message": "식당 변경", "label": "식당 변경"}]}}
    cases = {key: {"customer_id": customer_id, "state_json": state} for key, _ in rows}
    monkeypatch.setattr(case_dispatch.repository, "get_case", lambda _, **kwargs: cases[kwargs["case_id"]])
    seen, reads = [], []

    def recent(_, **kwargs):
        reads.append(kwargs)
        if latest == "none":
            return []
        return [{"role": "assistant", "case_id": str(waiting) if latest == "same" else
                 None if latest == "unknown" else str(uuid4())}, {"role": "customer"}]

    monkeypatch.setattr(chat_log, "recent", recent)
    def resume(**kwargs):
        seen.append(kwargs)
        return {"synthetic": True}
    controller = SimpleNamespace(resume=resume, resume_customer_input=resume)
    monkeypatch.setattr(case_dispatch, "response", lambda **kwargs: kwargs)
    call = lambda: case_dispatch.resume_pending(conn, controller=controller, tenant="travel-recency-test",
        trip={"trip_id": trip_id, "customer_id": customer_id}, request_id="reply-one", message=message,
        actor_id="test", case_id=waiting if explicit else None, token="synthetic-token" if token else None,
        expected_version=None)
    return call, seen, reads, conn, waiting, trip_id


@pytest.mark.parametrize("message", ["1", "1번", "1번이요", "1번째!", " 1번요. "])
def test_number_after_a_new_fact_does_not_resume_the_old_question(monkeypatch, message):
    call, seen, reads, conn, _, trip_id = prepare(monkeypatch, message=message)
    assert call() is None
    assert not seen and conn.commits == 0
    assert reads == [{"tenant_id": "travel-recency-test", "trip_id": trip_id}]


@pytest.mark.parametrize("latest", ["same", "none", "unknown"])
def test_same_question_and_legacy_history_keep_resume(monkeypatch, latest):
    call, seen, _, conn, waiting, _ = prepare(monkeypatch, latest=latest)
    assert call()["case_id"] == waiting
    assert len(seen) == 1 and conn.commits == 1


@pytest.mark.parametrize("kind", ["explicit", "token", "replayed"])
def test_explicit_or_replayed_reply_keeps_its_case_after_new_fact(monkeypatch, kind):
    call, seen, reads, _, waiting, _ = prepare(monkeypatch, **{kind: True})
    assert call()["case_id"] == waiting
    assert seen[0]["case_id"] == waiting and reads == []


@pytest.mark.parametrize("message,schema", [
    ("식당 변경", None), ("30분이요", {"required": ["minutes"]}),
])
def test_named_choice_and_typed_duration_keep_existing_matcher(monkeypatch, message, schema):
    call, seen, reads, _, waiting, _ = prepare(monkeypatch, message=message, schema=schema)
    assert call()["case_id"] == waiting
    assert len(seen) == 1 and reads == []


def test_ambiguous_legacy_number_still_requires_a_case(monkeypatch):
    call, seen, _, _, _, _ = prepare(monkeypatch, latest="none", extra=True)
    with pytest.raises(StateConflict, match="업무를 지정"):
        call()
    assert seen == []
